% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"page 13 question 3a; teacher page 71"}
\begin{tikzpicture}[x=11mm,y=7mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-2.7,-2.8) rectangle (4.1,6.5);
\draw[line width=.5pt,->] (-2.6,0)--(2.7,0) node[right] {$x$};
\draw[line width=.5pt,->] (0,-2.7)--(0,6.1) node[above] {$y$};
\draw[dashed,line width=.4pt] (-2.6,1)--(2.5,1) node[right] {$y=1$};
\draw[dashed,line width=.4pt] (-2.6,-2)--(2.5,-2) node[right] {$y=-2$};
\draw[line width=.8pt,domain=-2.5:1.5,samples=80] plot (\x,{pow(3,\x)+1});
\draw[line width=.8pt,domain=-2.5:1.5,samples=80] plot (\x,{pow(3,\x)});
\draw[line width=.8pt,domain=-2.5:1.5,samples=80] plot (\x,{pow(3,\x)-2});
\node[right] at (1.5,6.2) {$y=3^x+1$};
\node[right] at (1.5,5.1) {$y=3^x$};
\node[right] at (1.5,3.2) {$y=3^x-2$};
\foreach \v in {-1,2}{\fill (0,\v) circle (1pt);\node[left] at (0,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\end{tikzpicture}

% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"page 13 question 3b; teacher page 71"}
\begin{tikzpicture}[x=13mm,y=8mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-2.4,-1.4) rectangle (4.3,6.8);
\draw[line width=.5pt,->] (-2.3,0)--(2.5,0) node[right] {$x$};
\draw[line width=.5pt,->] (0,-.6)--(0,6.5) node[above] {$y$};
\draw[line width=.8pt,domain=-2.2:.68,samples=80] plot (\x,{2*pow(5,\x)});
\draw[line width=.8pt,domain=-2.2:1.1,samples=80] plot (\x,{pow(5,\x)});
\draw[line width=.8pt,domain=-2.2:1.5,samples=80] plot (\x,{.5*pow(5,\x)});
\node[right] at (.68,6.1) {$y=2\times5^x$};
\node[right] at (1.1,5.4) {$y=5^x$};
\node[right] at (1.5,4.6) {$y=\frac12\times5^x$};
\foreach \v in {1,2}{\fill (0,\v) circle (1pt);\node[left] at (0,\v) {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};}
\fill (0,.5) circle (1pt);
\draw[line width=.4pt] (0,.5)--(.6,-.7) node[below] {\special{dvisvgm:raw <g data-graph-text="tick">}$\frac12$\special{dvisvgm:raw </g>}};
\end{tikzpicture}

% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"page 13 question 3c; teacher page 71"}
\begin{tikzpicture}[x=11mm,y=9mm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-3.3,-.8) rectangle (3.3,5.6);
\draw[line width=.5pt,->] (-3.1,0)--(3.1,0) node[right] {$x$};
\draw[line width=.5pt,->] (0,-.7)--(0,5.1) node[above] {$y$};
\draw[line width=.8pt,domain=-3:2.2,samples=80] plot (\x,{pow(2,\x)});
\draw[line width=.8pt,domain=-2.2:3,samples=80] plot (\x,{pow(2,-\x)});
\node[above] at (2.1,4.6) {$y=2^x$};
\node[above] at (-2.1,4.6) {$y=2^{-x}$};
\fill (-1,2) circle (1pt) node[left] {$(-1,2)$};
\fill (1,2) circle (1pt) node[right] {$(1,2)$};
\fill (0,1) circle (1pt);
\node[above left] at (0,1) {\special{dvisvgm:raw <g data-graph-text="tick">}$1$\special{dvisvgm:raw </g>}};
\end{tikzpicture}

