\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-3.5,-.8) rectangle (3.5,5.8);
\draw[line width=.5pt,->] (-3.1,0)--(3.1,0) node[right] {$x$};
\draw[line width=.5pt,->] (0,-.7)--(0,5.1) node[above] {$y$};
